<div class="d-flex justify-content-between mb-3"><h2>Invoice</h2><?php if(is_role('Finance')):?><a class="btn btn-primary" href="<?=site_url('invoices/create')?>">+ Buat Invoice</a><?php endif;?></div><table class="table"><thead><tr><th>Nomor Invoice</th><th>PO</th><th>Tanggal</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r->invoice_number?></td><td><?=$r->po_number?></td><td><?=$r->invoice_date?></td><td><?=rupiah($r->total_invoice)?></td><td><span class="badge text-bg-<?= $r->status==='Paid'?'success':($r->status==='Rejected'?'danger':'secondary')?>"><?=$r->status?></span></td><td><?php if(is_role('Finance')):if($r->status==='Draft'):?><a class="btn btn-sm btn-outline-primary" href="<?=site_url('invoices/edit/'.$r->invoice_id)?>">Edit</a><?php endif;?><button class="btn btn-sm btn-outline-dark" data-bs-toggle="modal" data-bs-target="#status<?=$r->invoice_id?>">Status</button><div class="modal fade" id="status<?=$r->invoice_id?>"><div class="modal-dialog"><div class="modal-content"><div class="modal-body"><?=form_open('invoices/status/'.$r->invoice_id)?><label class="form-label">Status</label><select class="form-select mb-2" name="status"><option>Draft</option><option>Submitted</option><option>Paid</option><option>Rejected</option></select><textarea class="form-control mb-2" name="reject_note" placeholder="Alasan reject (wajib bila Rejected)"></textarea><button class="btn btn-primary">Simpan</button><?=form_close()?></div></div></div></div><?php endif;?></td></tr><?php endforeach;?></tbody></table>
